'''
Clump Finding Problem: Find patterns forming clumps in a string.
     Input: A string Genome, and integers k, L, and t.
     Output: All distinct k-mers forming (L, t)-clumps in Genome.

FindClumps(Text, k, L, t)
    Patterns ← an array of strings of length 0
    n ← |Text|
    for every integer i between 0 and n − L
        Window ← Text(i, L)
        freqMap ← FrequencyTable(Window, k)
        for every key s in freqMap
            if freqMap[s] ≥ t
                append s to Patterns
    remove duplicates from Patterns
    return Patterns
'''

def FrequencyTable(Text, k):
    freqMap = dict()
    for i in range(0, len(Text) - k + 1):
        freqMap[Text[i: i + k]] = freqMap.get(Text[i: i + k], 0) + 1
    return freqMap

# def FindClumps(Genome, k, L, t):
#     Patterns = set()
#     n = len(Genome)
#     for i in range(0, n - L + 1):
#         Window = Genome[i:i +L]
#         freqMap = FrequencyTable(Window, k)
#         for s in freqMap.keys():
#             if freqMap[s] >= t:
#                 Patterns.add(s)
#     # return Patterns
#     return " ".join(Patterns)

def FindClumps(Genome, k, L, t):
    Patterns = set()
    n = len(Genome)

    Window = Genome[:L]
    freqMap = FrequencyTable(Window, k)
    for s in freqMap.keys():
        if freqMap[s] >= t:
            Patterns.add(s)

    for i in range(1, n - L + 1):
        # Remove the k-mer that's sliding out
        left = Genome[i - 1:i - 1 + k]
        freqMap[left] -= 1
        if freqMap[left] == 0:
            del freqMap[left]

        right = Genome[i + L - k:i + L]
        freqMap[right] = freqMap.get(right, 0) + 1

        if freqMap[right] >= t:
            Patterns.add(right)
    return Patterns

if __name__ == "__main__":
    for i in range(4):
        file_input = open(f"ClumpFinding/inputs/input_{i + 1}.txt")
        file_input_text = file_input.readlines()
        Genome = file_input_text[0].strip()
        k, L, t = map(int, file_input_text[1].strip().split())

        file_output = open(f"ClumpFinding/outputs/output_{i + 1}.txt")
        file_output_text = file_output.read().strip()

        if set(file_output_text.split()) == FindClumps(Genome, k, L, t):
            print("yes")
        else:
            print(f"{i+1} no {FindClumps(Genome, k, L, t)}, {file_output_text}")
    
    Genome  = ""
    k, L, t =  9, 500, 3
    print(len(FindClumps(Genome, k, L, t)))

